// Vendored from the Agentic Owners policy core; see README.md in this
// directory. Precedence must stay identical to the source's.

import { posix } from "node:path";
import { AGENTIC_OWNERS_DIR } from "./constants.js";
import { blocksGlobalOverride, mergeGlobalOverride } from "./globalOverride.js";
import { patternMatchesFile, patternSpecificity } from "./matching.js";
import type {
  AgenticOwnersMatchedConfig,
  AgenticOwnersPathRule,
  AgenticOwnersRepoConfig,
} from "./types.js";

type PathScopedRule = {
  readonly scopeDepth: number;
  readonly sourcePath: string;
  readonly paths: readonly string[];
  /** Root-only repository-wide exemption, produced from `global_exclusions`. */
  readonly globalExclusion?: boolean;
  /**
   * Root `global_overrides` entry. Applied after precedence, not as a
   * candidate for it.
   */
  readonly globalOverride?: boolean;
};

/**
 * Convert a repository-relative changed path to the path seen by a policy.
 *
 * `foo/.agentic-owners/policy.yml` owns the `foo/` scope, so its `paths`
 * entries match against filenames relative to `foo/`. Root policies continue
 * to see repository-relative paths. Explicit leading `../` segments can
 * address a sibling tree.
 */
function filepathRelativeToPolicyScope({
  sourcePath,
  filepath,
}: {
  sourcePath: string;
  filepath: string;
}): string {
  const normalizedSourcePath = sourcePath.replace(/^\/+/, "");
  const normalizedFilepath = filepath.replace(/^\/+/, "");
  const marker = `/${AGENTIC_OWNERS_DIR}/`;
  const markerIndex = normalizedSourcePath.lastIndexOf(marker);
  if (markerIndex < 0) {
    return normalizedFilepath;
  }

  const scope = normalizedSourcePath.slice(0, markerIndex);
  return posix.relative(scope, normalizedFilepath);
}

function patternMatchesFileFromPolicy({
  rule,
  pattern,
  filepath,
}: {
  rule: PathScopedRule;
  pattern: string;
  filepath: string;
}): boolean {
  const relativeFilepath = filepathRelativeToPolicyScope({
    sourcePath: rule.sourcePath,
    filepath,
  });
  const filepathIsOutsideScope = relativeFilepath === ".." || relativeFilepath.startsWith("../");
  if (filepathIsOutsideScope && !pattern.startsWith("../")) {
    return false;
  }
  const slashlessPatternMatchesOnlyPolicyRoot = pattern !== "**" && !pattern.includes("/");
  if (slashlessPatternMatchesOnlyPolicyRoot && relativeFilepath.includes("/")) {
    return false;
  }
  return patternMatchesFile(pattern, relativeFilepath);
}

function ruleMatchesFile({ rule, filepath }: { rule: PathScopedRule; filepath: string }): boolean {
  return rule.paths.some((pattern) =>
    patternMatchesFileFromPolicy({
      rule,
      pattern,
      filepath,
    }),
  );
}

function bestMatchingPatternSpecificity(rule: PathScopedRule, filepath: string): number {
  let best = 0;
  for (const pattern of rule.paths) {
    if (patternMatchesFileFromPolicy({ rule, pattern, filepath })) {
      best = Math.max(best, patternSpecificity(pattern));
    }
  }
  return best;
}

function compareRulePrecedence(
  left: PathScopedRule,
  right: PathScopedRule,
  filepath?: string,
): number {
  // Root `global_exclusions` model repository-wide owner-clearing rules. They
  // must win before normal closest-directory precedence or every nested policy
  // would need to repeat the same carve-outs. Parsing only permits them in the
  // root policy, and the caller reads that policy from the base branch first.
  const leftGlobalExclusion = left.globalExclusion === true;
  const rightGlobalExclusion = right.globalExclusion === true;
  if (leftGlobalExclusion !== rightGlobalExclusion) {
    return leftGlobalExclusion ? 1 : -1;
  }
  if (left.scopeDepth !== right.scopeDepth) {
    return left.scopeDepth - right.scopeDepth;
  }
  if (filepath !== undefined) {
    const leftSpecificity = bestMatchingPatternSpecificity(left, filepath);
    const rightSpecificity = bestMatchingPatternSpecificity(right, filepath);
    if (leftSpecificity !== rightSpecificity) {
      return leftSpecificity - rightSpecificity;
    }
  }
  return left.sourcePath.localeCompare(right.sourcePath);
}

function selectRuleForFile(
  filepath: string,
  rules: readonly AgenticOwnersPathRule[],
): {
  readonly winner: { readonly rule: AgenticOwnersPathRule; readonly order: number } | undefined;
  readonly overrides: readonly { readonly rule: AgenticOwnersPathRule; readonly order: number }[];
} {
  let winner: { readonly rule: AgenticOwnersPathRule; readonly order: number } | undefined;
  const overrides: { readonly rule: AgenticOwnersPathRule; readonly order: number }[] = [];
  for (const [order, rule] of rules.entries()) {
    if (!ruleMatchesFile({ rule, filepath })) {
      continue;
    }
    if (rule.globalOverride === true) {
      overrides.push({ rule, order });
      continue;
    }
    if (winner === undefined || compareRulePrecedence(rule, winner.rule, filepath) > 0) {
      winner = { rule, order };
    }
  }
  return { winner, overrides };
}

function teamsSkippedByOverride(
  winner: AgenticOwnersPathRule,
  override: AgenticOwnersPathRule,
): boolean {
  const skipped = override.skipTeams;
  if (skipped === undefined || skipped.length === 0) {
    return false;
  }
  const names = new Set(skipped.map((team) => team.trim().toLowerCase()));
  return winner.teams.some((team) => names.has(team.trim().toLowerCase()));
}

function overrideAppliesToFile(
  override: AgenticOwnersPathRule,
  winner: AgenticOwnersPathRule,
  filepath: string,
): boolean {
  if (teamsSkippedByOverride(winner, override)) {
    return false;
  }
  const skipPaths = override.skipPaths;
  if (skipPaths === undefined || skipPaths.length === 0) {
    return true;
  }
  return !ruleMatchesFile({ rule: { ...override, paths: skipPaths }, filepath });
}

function effectiveRuleSelector(
  rules: readonly AgenticOwnersPathRule[],
): (filepath: string) => AgenticOwnersPathRule | undefined {
  const cache = new Map<string, AgenticOwnersPathRule>();
  return (filepath) => {
    const { winner, overrides } = selectRuleForFile(filepath, rules);
    if (winner === undefined || blocksGlobalOverride(winner.rule)) {
      return winner?.rule;
    }
    const applicable = overrides.filter((entry) =>
      overrideAppliesToFile(entry.rule, winner.rule, filepath),
    );
    if (applicable.length === 0) {
      return winner.rule;
    }
    const key = `${winner.order}:${applicable.map((entry) => entry.order).join(",")}`;
    const cached = cache.get(key);
    if (cached !== undefined) {
      return cached;
    }
    const effective = mergeGlobalOverride(
      winner.rule,
      applicable.map((entry) => entry.rule),
    );
    cache.set(key, effective);
    return effective;
  };
}

export function matchRepoConfigForChangedFiles({
  changedFiles,
  config,
}: {
  changedFiles: readonly string[];
  config: AgenticOwnersRepoConfig;
}): AgenticOwnersMatchedConfig {
  // Dedupe by rule identity, not sourcePath: two different rules in the same
  // policy.yml can each win for different changed files, and collapsing them by
  // file path would silently drop one (e.g. a hard-gate rule lost behind an
  // advisory rule from the same policy).
  const winners = new Set<AgenticOwnersPathRule>();
  const ruleForFile = effectiveRuleSelector(config.rules);
  for (const filepath of changedFiles) {
    const winner = ruleForFile(filepath);
    if (winner !== undefined) {
      winners.add(winner);
    }
  }
  return {
    matchedRules: [...winners].sort((left, right) => compareRulePrecedence(left, right)),
  };
}

/**
 * The changed files that NO rule wins — not owned, not carved out, not
 * globally excluded. These are the files that enroll a change through the
 * default fallback: a file won by an ownerless carve-out or an exclusion was
 * deliberately opted out, but a file nothing matches has simply never been
 * governed and still deserves a risk review.
 *
 * Pure; the caller passes the already-loaded rule set (committed policy rules
 * plus the synthetic `global_exclusions` rule) and the reviewable file set.
 */
export function changedFilesWithoutWinningRule({
  changedFiles,
  rules,
}: {
  changedFiles: readonly string[];
  rules: readonly AgenticOwnersPathRule[];
}): string[] {
  const ruleForFile = effectiveRuleSelector(rules);
  return changedFiles.filter((filepath) => ruleForFile(filepath) === undefined);
}

/**
 * True when there is at least one changed file AND every one of them is won by a
 * root `global_exclusions` rule. Such a PR is inherently low risk (it only
 * touches globally-excluded paths — Bazel files, generated trees, …), so it
 * keeps a clean not-enrolled pass: no risk assessment, no reviewer inference.
 * An empty file set, an unmatched file, or a file won by any non-exclusion rule
 * all make this false.
 */
export function everyChangedFileGloballyExcluded({
  changedFiles,
  rules,
}: {
  changedFiles: readonly string[];
  rules: readonly AgenticOwnersPathRule[];
}): boolean {
  if (changedFiles.length === 0) {
    return false;
  }
  const ruleForFile = effectiveRuleSelector(rules);
  return changedFiles.every((filepath) => ruleForFile(filepath)?.globalExclusion === true);
}

function hasOwners(rule: AgenticOwnersPathRule): boolean {
  return rule.teams.length > 0 || rule.users.length > 0;
}

/**
 * Keep only owned policy rules — drop ownerless precedence carve-outs
 * (`always_approve`, `global_exclusions`), which intentionally clear broader
 * ownership and must not enroll the review. This is the same enrollment
 * signal the CI gate uses, so "which PRs the agent reviews" cannot drift
 * from "which PRs the gate blocks".
 */
export function committedMatchedRules(
  rules: readonly AgenticOwnersPathRule[],
): AgenticOwnersPathRule[] {
  return rules.filter(hasOwners);
}
